import inspect
import signal

from taf.selenium.core.exceptions import TimeoutException, NoTimeoutSpecifiedError


class TimeoutContext:
    """Timeout context manager, will terminate with given timeout"""

    def __init__(self, timeout):
        self.timeout = timeout

        self._register_function_to_raise_timeout_error_on_signal()
        self._schedule_signal_to_be_sent_afer_time()

    def __enter__(self):
        pass

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._unregister_signal_to_not_be_sent_after_timeout_reached()

    def _register_function_to_raise_timeout_error_on_signal(self):
        signal.signal(signal.SIGALRM, self._raise_timeout)

    def _schedule_signal_to_be_sent_afer_time(self):
        signal.setitimer(signal.ITIMER_REAL, self.timeout)

    def _unregister_signal_to_not_be_sent_after_timeout_reached(self):
        signal.setitimer(signal.ITIMER_REAL, 0)

    @staticmethod
    def _raise_timeout(signum, frame):
        raise TimeoutException


class timeout:
    """Timeout decorator on function, requires 'timeout' argument to be declared."""

    def __init__(self, func):
        self.func = func

    def __call__(self, *args, **kwargs):
        timeout = self._get_timeout_value(*args, **kwargs)
        with TimeoutContext(timeout):
            return self.func(*args, **kwargs)

    def _get_timeout_value(self, *args, **kwargs):
        dictionary = self._get_all_function_args(*args, **kwargs)
        timeout = dictionary.get("timeout")
        if timeout is not None:
            return timeout
        else:
            raise NoTimeoutSpecifiedError("Timeout argument required to decorate function")

    def _get_all_function_args(self, *args, **kwargs):
        """Default values of named arguments are not available in *args and **kwargs when decorating,
         so it needs to be extracted other way"""
        return inspect.getcallargs(self.func, *args, **kwargs)
